    else:
        own_rate = 0.5  # default if no history

    # Lower the threshold if we have been stingy (own_rate < 0.4)
    # This encourages more cooperation when we have not donated much
    if own_rate < 0.4:
        threshold = -0.3  # more forgiving
    else:
        threshold = 0.0   # standard threshold

    return recipient_reputation > threshold

