_rep_counts = {}

def evaluate(current_reputation, observation, my_history, round_num):
    actor = observation.get('actor')
    action = observation.get('action')
    if actor is None or action is None:
        return current_reputation  # no update

    # Initialize counts for this actor if not present
    if actor not in _rep_counts:
        _rep_counts[actor] = {'d': 0, 'n': 0}

    # Update counts based on observation
    if action == 'donate':
        _rep_counts[actor]['d'] += 1
    else:
        _rep_counts[actor]['n'] += 1

    # Compute reputation as (donations - non-donations) / total
    d = _rep_counts[actor]['d']
    n = _rep_counts[actor]['n']
    total = d + n
    if total == 0:
        rep = 0.0
    else:
        rep = (d - n) / total

    # Bound to [-1.0, 1.0]
    rep = max(-1.0, min(1.0, rep))
    return rep


